[package]
name = "db"
version = "0.0.68"
edition = "2024"

[dependencies]
utils = { path = "../utils" }
executors = { path = "../executors" }
tokio = { workspace = true }
tokio-util = { version = "0.7", features = ["io"] }
thiserror = { workspace = true }
serde = { workspace = true }
serde_json = { workspace = true }
anyhow = { workspace = true }
tracing = { workspace = true }
tracing-subscriber = { workspace = true }
sqlx = { version = "0.8.6", features = ["runtime-tokio-rustls", "sqlite", "chrono", "uuid"] }
chrono = { version = "0.4", features = ["serde"] }
uuid = { version = "1.0", features = ["v4", "serde"] }
ts-rs = { workspace = true }
async-trait = "0.1"
regex = "1.11.1"
sentry-tracing = { version = "0.41.0", features = ["backtrace"] }
futures-util = "0.3"

PRAGMA foreign_keys = ON;
CREATE TABLE projects ( id BLOB PRIMARY KEY, name TEXT NOT NULL, git_repo_path TEXT NOT NULL DEFAULT '' UNIQUE, setup_script TEXT DEFAULT '', created_at TEXT NOT NULL DEFAULT (datetime('now', 'subsec')), updated_at TEXT NOT NULL DEFAULT (datetime('now', 'subsec')) );
CREATE TABLE tasks ( id BLOB PRIMARY KEY, project_id BLOB NOT NULL, title TEXT NOT NULL, description TEXT, status TEXT NOT NULL DEFAULT 'todo' CHECK (status IN ('todo','inprogress','done','cancelled','inreview')), created_at TEXT NOT NULL DEFAULT (datetime('now', 'subsec')), updated_at TEXT NOT NULL DEFAULT (datetime('now', 'subsec')), FOREIGN KEY (project_id) REFERENCES projects(id) ON DELETE CASCADE );
CREATE TABLE task_attempts ( id BLOB PRIMARY KEY, task_id BLOB NOT NULL, worktree_path TEXT NOT NULL, merge_commit TEXT, executor TEXT, stdout TEXT, stderr TEXT, created_at TEXT NOT NULL DEFAULT (datetime('now', 'subsec')), updated_at TEXT NOT NULL DEFAULT (datetime('now', 'subsec')), FOREIGN KEY (task_id) REFERENCES tasks(id) ON DELETE CASCADE );
CREATE TABLE task_attempt_activities ( id BLOB PRIMARY KEY, task_attempt_id BLOB NOT NULL, status TEXT NOT NULL DEFAULT 'init' CHECK (status IN ('init','setuprunning','setupcomplete','setupfailed','executorrunning','executorcomplete','executorfailed','paused')), note TEXT, created_at TEXT NOT NULL DEFAULT (datetime('now', 'subsec')), FOREIGN KEY (task_attempt_id) REFERENCES task_attempts(id) ON DELETE CASCADE );

PRAGMA foreign_keys = ON;
CREATE TABLE execution_processes ( id BLOB PRIMARY KEY, task_attempt_id BLOB NOT NULL, process_type TEXT NOT NULL DEFAULT 'setupscript' CHECK (process_type IN ('setupscript','codingagent','devserver')), status TEXT NOT NULL DEFAULT 'running' CHECK (status IN ('running','completed','failed','killed')), command TEXT NOT NULL, args TEXT, -- JSON array of arguments working_directory TEXT NOT NULL, stdout TEXT, stderr TEXT, exit_code INTEGER, started_at TEXT NOT NULL DEFAULT (datetime('now', 'subsec')), completed_at TEXT, created_at TEXT NOT NULL DEFAULT (datetime('now', 'subsec')), updated_at TEXT NOT NULL DEFAULT (datetime('now', 'subsec')), FOREIGN KEY (task_attempt_id) REFERENCES task_attempts(id) ON DELETE CASCADE );
CREATE INDEX idx_execution_processes_task_attempt_id ON execution_processes(task_attempt_id); CREATE INDEX idx_execution_processes_status ON execution_processes(status); CREATE INDEX idx_execution_processes_type ON execution_processes(process_type);

PRAGMA foreign_keys = ON;
-- Remove stdout and stderr columns from task_attempts table -- These are now tracked in the execution_processes table for better granularity
-- SQLite doesn't support DROP COLUMN directly, so we need to recreate the table -- First, create a new table without stdout and stderr CREATE TABLE task_attempts_new ( id BLOB PRIMARY KEY, task_id BLOB NOT NULL, worktree_path TEXT NOT NULL, merge_commit TEXT, executor TEXT, created_at TEXT NOT NULL DEFAULT (datetime('now', 'subsec')), updated_at TEXT NOT NULL DEFAULT (datetime('now', 'subsec')), FOREIGN KEY (task_id) REFERENCES tasks(id) ON DELETE CASCADE );
-- Copy data from old table to new table (excluding stdout and stderr) INSERT INTO task_attempts_new (id, task_id, worktree_path, merge_commit, executor, created_at, updated_at) SELECT id, task_id, worktree_path, merge_commit, executor, created_at, updated_at FROM task_attempts;
-- Drop the old table DROP TABLE task_attempts;
-- Rename the new table to the original name ALTER TABLE task_attempts_new RENAME TO task_attempts;

-- Migration to relate task_attempt_activities to execution_processes instead of task_attempts -- This migration will: -- 1. Drop and recreate the task_attempt_activities table with execution_process_id -- 2. Clear existing data as it cannot be migrated meaningfully
-- Drop the existing table (this will wipe existing activity data) DROP TABLE IF EXISTS task_attempt_activities;
-- Create the new table structure with execution_process_id foreign key CREATE TABLE task_attempt_activities ( id TEXT PRIMARY KEY, execution_process_id TEXT NOT NULL REFERENCES execution_processes(id) ON DELETE CASCADE, status TEXT NOT NULL, note TEXT, created_at DATETIME NOT NULL DEFAULT (datetime('now')), FOREIGN KEY (execution_process_id) REFERENCES execution_processes(id) ON DELETE CASCADE );
-- Create index for efficient lookups by execution_process_id CREATE INDEX idx_task_attempt_activities_execution_process_id ON task_attempt_activities(execution_process_id);
-- Create index for efficient lookups by created_at for ordering CREATE INDEX idx_task_attempt_activities_created_at ON task_attempt_activities(created_at);

PRAGMA foreign_keys = ON;

CREATE TABLE executor_sessions (
    id                    BLOB PRIMARY KEY,
    task_attempt_id       BLOB NOT NULL,
    execution_process_id  BLOB NOT NULL,
    session_id            TEXT,  -- External session ID from Claude/Amp
    prompt                TEXT,  -- The prompt sent to the executor
    created_at            TEXT NOT NULL DEFAULT (datetime('now', 'subsec')),
    updated_at            TEXT NOT NULL DEFAULT (datetime('now', 'subsec')),
    FOREIGN KEY (task_attempt_id) REFERENCES task_attempts(id) ON DELETE CASCADE,
    FOREIGN KEY (execution_process_id) REFERENCES execution_processes(id) ON DELETE CASCADE
);

CREATE INDEX idx_executor_sessions_task_attempt_id ON executor_sessions(task_attempt_id);
