use std::path::PathBuf;
use chrono::{DateTime, Utc}; use serde::{Deserialize, Serialize}; use sqlx::{FromRow, SqlitePool}; use thiserror::Error; use ts_rs::TS; use uuid::Uuid;
#[derive(Debug, Error)] pub enum ProjectError { #[error(transparent)] Database(#[from] sqlx::Error), #[error("Project not found")] ProjectNotFound, #[error("Project with git repository path already exists")] GitRepoPathExists, #[error("Failed to check existing git repository path: {0}")] GitRepoCheckFailed(String), #[error("Failed to create project: {0}")] CreateFailed(String), }
#[derive(Debug, Clone, FromRow, Serialize, Deserialize, TS)] pub struct Project { pub id: Uuid, pub name: String, pub git_repo_path: PathBuf, pub setup_script: Option<String>, pub dev_script: Option<String>, pub cleanup_script: Option<String>, pub copy_files: Option<String>,
#[ts(type = "Date")] pub created_at: DateTime<Utc>, #[ts(type = "Date")] pub updated_at: DateTime<Utc>, }
#[derive(Debug, Deserialize, TS)] pub struct CreateProject { pub name: String, pub git_repo_path: String, pub use_existing_repo: bool, pub setup_script: Option<String>, pub dev_script: Option<String>, pub cleanup_script: Option<String>, pub copy_files: Option<String>, }
#[derive(Debug, Deserialize, TS)] pub struct UpdateProject { pub name: Option<String>, pub git_repo_path: Option<String>, pub setup_script: Option<String>, pub dev_script: Option<String>, pub cleanup_script: Option<String>, pub copy_files: Option<String>, }
#[derive(Debug, Serialize, TS)] pub struct ProjectWithBranch { pub id: Uuid, pub name: String, pub git_repo_path: PathBuf, pub setup_script: Option<String>, pub dev_script: Option<String>, pub cleanup_script: Option<String>, pub copy_files: Option<String>, pub current_branch: Option<String>,
#[ts(type = "Date")] pub created_at: DateTime<Utc>, #[ts(type = "Date")] pub updated_at: DateTime<Utc>, }
impl ProjectWithBranch { pub fn from_project(project: Project, current_branch: Option<String>) -> Self { Self { id: project.id, name: project.name, git_repo_path: project.git_repo_path, setup_script: project.setup_script, dev_script: project.dev_script, cleanup_script: project.cleanup_script, copy_files: project.copy_files, current_branch, created_at: project.created_at, updated_at: project.updated_at, } } }
#[derive(Debug, Serialize, TS)] pub struct SearchResult { pub path: String, pub is_file: bool, pub match_type: SearchMatchType, }
#[derive(Debug, Serialize, TS)] pub enum SearchMatchType { FileName, DirectoryName, FullPath, }
impl Project { pub async fn find_all(pool: &SqlitePool) -> Result<Vec<Self>, sqlx::Error> { sqlx::query_as!( Project, r#"SELECT id as "id!: Uuid", name, git_repo_path, setup_script, dev_script, cleanup_script, copy_files, created_at as "created_at!: DateTime<Utc>", updated_at as "updated_at!: DateTime<Utc>" FROM projects ORDER BY created_at DESC"# ) .fetch_all(pool) .await }
pub async fn find_by_id(pool: &SqlitePool, id: Uuid) -> Result<Option<Self>, sqlx::Error> { sqlx::query_as!( Project, r#"SELECT id as "id!: Uuid", name, git_repo_path, setup_script, dev_script, cleanup_script, copy_files, created_at as "created_at!: DateTime<Utc>", updated_at as "updated_at!: DateTime<Utc>" FROM projects WHERE id = $1"#, id ) .fetch_optional(pool) .await }
pub async fn find_by_git_repo_path( pool: &SqlitePool, git_repo_path: &str, ) -> Result<Option<Self>, sqlx::Error> { sqlx::query_as!( Project, r#"SELECT id as "id!: Uuid", name, git_repo_path, setup_script, dev_script, cleanup_script, copy_files, created_at as "created_at!: DateTime<Utc>", updated_at as "updated_at!: DateTime<Utc>" FROM projects WHERE git_repo_path = $1"#, git_repo_path ) .fetch_optional(pool) .await }
pub async fn find_by_git_repo_path_excluding_id( pool: &SqlitePool, git_repo_path: &str, exclude_id: Uuid, ) -> Result<Option<Self>, sqlx::Error> { sqlx::query_as!( Project, r#"SELECT id as "id!: Uuid", name, git_repo_path, setup_script, dev_script, cleanup_script, copy_files, created_at as "created_at!: DateTime<Utc>", updated_at as "updated_at!: DateTime<Utc>" FROM projects WHERE git_repo_path = $1 AND id != $2"#, git_repo_path, exclude_id ) .fetch_optional(pool) .await }
pub async fn create( pool: &SqlitePool, data: &CreateProject, project_id: Uuid, ) -> Result<Self, sqlx::Error> { sqlx::query_as!( Project, r#"INSERT INTO projects (id, name, git_repo_path, setup_script, dev_script, cleanup_script, copy_files) VALUES ($1, $2, $3, $4, $5, $6, $7) RETURNING id as "id!: Uuid", name, git_repo_path, setup_script, dev_script, cleanup_script, copy_files, created_at as "created_at!: DateTime<Utc>", updated_at as "updated_at!: DateTime<Utc>""#, project_id, data.name, data.git_repo_path, data.setup_script, data.dev_script, data.cleanup_script, data.copy_files ) .fetch_one(pool) .await }
pub async fn update( pool: &SqlitePool, id: Uuid, name: String, git_repo_path: String, setup_script: Option<String>, dev_script: Option<String>, cleanup_script: Option<String>, copy_files: Option<String>, ) -> Result<Self, sqlx::Error> { sqlx::query_as!( Project, r#"UPDATE projects SET name = $2, git_repo_path = $3, setup_script = $4, dev_script = $5, cleanup_script = $6, copy_files = $7 WHERE id = $1 RETURNING id as "id!: Uuid", name, git_repo_path, setup_script, dev_script, cleanup_script, copy_files, created_at as "created_at!: DateTime<Utc>", updated_at as "updated_at!: DateTime<Utc>""#, id, name, git_repo_path, setup_script, dev_script, cleanup_script, copy_files ) .fetch_one(pool) .await }
pub async fn delete(pool: &SqlitePool, id: Uuid) -> Result<u64, sqlx::Error> { let result = sqlx::query!("DELETE FROM projects WHERE id = $1", id) .execute(pool) .await?; Ok(result.rows_affected()) }
pub async fn exists(pool: &SqlitePool, id: Uuid) -> Result<bool, sqlx::Error> { let result = sqlx::query!( r#" SELECT COUNT(*) as "count!: i64" FROM projects WHERE id = $1 "#, id ) .fetch_one(pool) .await?;
Ok(result.count > 0) } }

use chrono::{DateTime, Utc};
use serde::{Deserialize, Serialize};
use sqlx::{FromRow, SqlitePool, Type};
use thiserror::Error;
use ts_rs::TS;
use uuid::Uuid;

use super::{project::Project, task::Task};

#[derive(Debug, Error)]
pub enum TaskAttemptError {
    #[error(transparent)]
    Database(#[from] sqlx::Error),
    #[error("Task not found")]
    TaskNotFound,
    #[error("Project not found")]
    ProjectNotFound,
    #[error("Validation error: {0}")]
    ValidationError(String),
    #[error("Branch not found: {0}")]
    BranchNotFound(String),
}

#[derive(Debug, Clone, Type, Serialize, Deserialize, PartialEq, TS)]
#[sqlx(type_name = "task_attempt_status", rename_all = "lowercase")]
#[serde(rename_all = "lowercase")]
pub enum TaskAttemptStatus {
    SetupRunning,
    SetupComplete,
    SetupFailed,
    ExecutorRunning,
    ExecutorComplete,
    ExecutorFailed,
}

#[derive(Debug, Clone, FromRow, Serialize, Deserialize, TS)]
pub struct TaskAttempt {
    pub id: Uuid,
    pub task_id: Uuid,                 // Foreign key to Task
    pub container_ref: Option<String>, // Path to a worktree (local), or cloud container id
    pub branch: Option<String>,        // Git branch name for this task attempt
    pub base_branch: String,           // Base branch this attempt is based on
    pub profile: String, // Name of the base coding agent to use ("AMP", "CLAUDE_CODE",
    // "GEMINI", etc.)
    pub worktree_deleted: bool, // Flag indicating if worktree has been cleaned up
    pub setup_completed_at: Option<DateTime<Utc>>, // When setup script was last completed
    pub created_at: DateTime<Utc>,
    pub updated_at: DateTime<Utc>,
}

/// GitHub PR creation parameters
pub struct CreatePrParams<'a> {
    pub attempt_id: Uuid,
    pub task_id: Uuid,
    pub project_id: Uuid,
    pub github_token: &'a str,
    pub title: &'a str,
    pub body: Option<&'a str>,
    pub base_branch: Option<&'a str>,
}

#[derive(Debug, Deserialize, TS)]
pub struct CreateFollowUpAttempt {
    pub prompt: String,
}

/// Context data for resume operations (simplified)
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct AttemptResumeContext {
    pub execution_history: String,
    pub cumulative_diffs: String,
}

#[derive(Debug)]
pub struct TaskAttemptContext {
    pub task_attempt: TaskAttempt,
    pub task: Task,
    pub project: Project,
}

#[derive(Debug, Deserialize, TS)]
pub struct CreateTaskAttempt {
    pub profile: String,
    pub base_branch: String,
}

impl TaskAttempt {
    pub async fn parent_task(&self, pool: &SqlitePool) -> Result<Option<Task>, sqlx::Error> {
        Task::find_by_id(pool, self.task_id).await
    }

    /// Fetch all task attempts, optionally filtered by task_id. Newest first.
    pub async fn fetch_all(
        pool: &SqlitePool,
        task_id: Option<Uuid>,
    ) -> Result<Vec<Self>, TaskAttemptError> {
        let attempts = match task_id {
            Some(tid) => sqlx::query_as!(
                TaskAttempt,
                r#"SELECT id AS "id!: Uuid",
                              task_id AS "task_id!: Uuid",
                              container_ref,
                              branch,
                              base_branch,
                              profile AS "profile!",
                              worktree_deleted AS "worktree_deleted!: bool",
                              setup_completed_at AS "setup_completed_at: DateTime<Utc>",
                              created_at AS "created_at!: DateTime<Utc>",
                              updated_at AS "updated_at!: DateTime<Utc>"
                       FROM task_attempts
                       WHERE task_id = $1
                       ORDER BY created_at DESC"#,
                tid
            )
            .fetch_all(pool)
            .await
            .map_err(TaskAttemptError::Database)?,
            None => sqlx::query_as!(
                TaskAttempt,
                r#"SELECT id AS "id!: Uuid",
                              task_id AS "task_id!: Uuid",
                              container_ref,
                              branch,
                              base_branch,
                              profile AS "profile!",
                              worktree_deleted AS "worktree_deleted!: bool",
                              setup_completed_at AS "setup_completed_at: DateTime<Utc>",
                              created_at AS "created_at!: DateTime<Utc>",
                              updated_at AS "updated_at!: DateTime<Utc>"
                       FROM task_attempts
                       ORDER BY created_at DESC"#
            )
            .fetch_all(pool)
            .await
            .map_err(TaskAttemptError::Database)?,
        };

        Ok(attempts)
    }

    /// Load task attempt with full validation - ensures task_attempt belongs to task and task belongs to project
    pub async fn load_context(
        pool: &SqlitePool,
        attempt_id: Uuid,
        task_id: Uuid,
        project_id: Uuid,
    ) -> Result<TaskAttemptContext, TaskAttemptError> {
        // Single query with JOIN validation to ensure proper relationships
        let task_attempt = sqlx::query_as!(
            TaskAttempt,
            r#"SELECT  ta.id                AS "id!: Uuid",
                       ta.task_id           AS "task_id!: Uuid",
                       ta.container_ref,
                       ta.branch,
                       ta.base_branch,
                       ta.profile AS "profile!",
                       ta.worktree_deleted  AS "worktree_deleted!: bool",
                       ta.setup_completed_at AS "setup_completed_at: DateTime<Utc>",
                       ta.created_at        AS "created_at!: DateTime<Utc>",
                       ta.updated_at        AS "updated_at!: DateTime<Utc>"
               FROM    task_attempts ta
               JOIN    tasks t ON ta.task_id = t.id
               JOIN    projects p ON t.project_id = p.id
               WHERE   ta.id = $1 AND t.id = $2 AND p.id = $3"#,
            attempt_id,
            task_id,
            project_id
        )
        .fetch_optional(pool)
        .await?
        .ok_or(TaskAttemptError::TaskNotFound)?;

        // Load task and project (we know they exist due to JOIN validation)
        let task = Task::find_by_id(pool, task_id)
            .await?
            .ok_or(TaskAttemptError::TaskNotFound)?;

        let project = Project::find_by_id(pool, project_id)
            .await?
            .ok_or(TaskAttemptError::ProjectNotFound)?;

        Ok(TaskAttemptContext {
            task_attempt,
            task,
            project,
        })
    }

    /// Update container reference
    pub async fn update_container_ref(
        pool: &SqlitePool,
        attempt_id: Uuid,
        container_ref: &str,
    ) -> Result<(), sqlx::Error> {
        let now = Utc::now();
        sqlx::query!(
            "UPDATE task_attempts SET container_ref = $1, updated_at = $2 WHERE id = $3",
            container_ref,
            now,
            attempt_id
        )
        .execute(pool)
        .await?;
        Ok(())
    }

    pub async fn update_branch(
        pool: &SqlitePool,
        attempt_id: Uuid,
        branch: &str,
    ) -> Result<(), sqlx::Error> {
        let now = Utc::now();
        sqlx::query!(
            "UPDATE task_attempts SET branch = $1, updated_at = $2 WHERE id = $3",
            branch,
            now,
            attempt_id
        )
        .execute(pool)
        .await?;
        Ok(())
    }

    /// Helper function to mark a worktree as deleted in the database
    pub async fn mark_worktree_deleted(
        pool: &SqlitePool,
        attempt_id: Uuid,
    ) -> Result<(), sqlx::Error> {
        sqlx::query!(
            "UPDATE task_attempts SET worktree_deleted = TRUE, updated_at = datetime('now') WHERE id = ?",
            attempt_id
        )
        .execute(pool)
        .await?;
        Ok(())
    }

    pub async fn find_by_id(pool: &SqlitePool, id: Uuid) -> Result<Option<Self>, sqlx::Error> {
        sqlx::query_as!(
            TaskAttempt,
            r#"SELECT  id                AS "id!: Uuid",
                       task_id           AS "task_id!: Uuid",
                       container_ref,
                       branch,
                       base_branch,
                       profile AS "profile!",
                       worktree_deleted  AS "worktree_deleted!: bool",
                       setup_completed_at AS "setup_completed_at: DateTime<Utc>",
                       created_at        AS "created_at!: DateTime<Utc>",
                       updated_at        AS "updated_at!: DateTime<Utc>"
               FROM    task_attempts
               WHERE   id = $1"#,
            id
        )
        .fetch_optional(pool)
        .await
    }

    pub async fn find_by_rowid(pool: &SqlitePool, rowid: i64) -> Result<Option<Self>, sqlx::Error> {
        sqlx::query_as!(
            TaskAttempt,
            r#"SELECT  id                AS "id!: Uuid",
                       task_id           AS "task_id!: Uuid",
                       container_ref,
                       branch,
                       base_branch,
                       profile AS "profile!",
                       worktree_deleted  AS "worktree_deleted!: bool",
                       setup_completed_at AS "setup_completed_at: DateTime<Utc>",
                       created_at        AS "created_at!: DateTime<Utc>",
                       updated_at        AS "updated_at!: DateTime<Utc>"
               FROM    task_attempts
               WHERE   rowid = $1"#,
            rowid
        )
        .fetch_optional(pool)
        .await
    }

    /// Find task attempts by task_id with project git repo path for cleanup operations
    pub async fn find_by_task_id_with_project(
        pool: &SqlitePool,
        task_id: Uuid,
    ) -> Result<Vec<(Uuid, Option<String>, String)>, sqlx::Error> {
        let records = sqlx::query!(
            r#"
            SELECT ta.id as "attempt_id!: Uuid", ta.container_ref, p.git_repo_path as "git_repo_path!"
            FROM task_attempts ta
            JOIN tasks t ON ta.task_id = t.id
            JOIN projects p ON t.project_id = p.id
            WHERE ta.task_id = $1
            "#,
            task_id
        )
        .fetch_all(pool)
        .await?;

        Ok(records
            .into_iter()
            .map(|r| (r.attempt_id, r.container_ref, r.git_repo_path))
            .collect())
    }

    pub async fn find_by_worktree_deleted(
        pool: &SqlitePool,
    ) -> Result<Vec<(Uuid, String)>, sqlx::Error> {
        let records = sqlx::query!(
        r#"SELECT id as "id!: Uuid", container_ref FROM task_attempts WHERE worktree_deleted = FALSE"#,
        )
        .fetch_all(pool).await?;
        Ok(records
            .into_iter()
            .filter_map(|r| r.container_ref.map(|path| (r.id, path)))
            .collect())
    }

    pub async fn container_ref_exists(
        pool: &SqlitePool,
        container_ref: &str,
    ) -> Result<bool, sqlx::Error> {
        let result = sqlx::query!(
            r#"SELECT EXISTS(SELECT 1 FROM task_attempts WHERE container_ref = ?) as "exists!: bool""#,
            container_ref
        )
        .fetch_one(pool)
        .await?;

        Ok(result.exists)
    }

    /// Find task attempts that are expired (72+ hours since last activity) and eligible for worktree cleanup
    /// Activity includes: execution completion, task attempt updates (including worktree recreation),
    /// and any attempts that are currently in progress
    pub async fn find_expired_for_cleanup(
        pool: &SqlitePool,
    ) -> Result<Vec<(Uuid, String, String)>, sqlx::Error> {
        let records = sqlx::query!(
            r#"
            SELECT ta.id as "attempt_id!: Uuid", ta.container_ref, p.git_repo_path as "git_repo_path!"
            FROM task_attempts ta
            LEFT JOIN execution_processes ep ON ta.id = ep.task_attempt_id AND ep.completed_at IS NOT NULL
            JOIN tasks t ON ta.task_id = t.id
            JOIN projects p ON t.project_id = p.id
            WHERE ta.worktree_deleted = FALSE
                -- Exclude attempts with any running processes (in progress)
                AND ta.id NOT IN (
                    SELECT DISTINCT ep2.task_attempt_id
                    FROM execution_processes ep2
                    WHERE ep2.completed_at IS NULL
                )
            GROUP BY ta.id, ta.container_ref, p.git_repo_path, ta.updated_at
            HAVING datetime('now', '-72 hours') > datetime(
                MAX(
                    CASE
                        WHEN ep.completed_at IS NOT NULL THEN ep.completed_at
                        ELSE ta.updated_at
                    END
                )
            )
            ORDER BY MAX(
                CASE
                    WHEN ep.completed_at IS NOT NULL THEN ep.completed_at
                    ELSE ta.updated_at
                END
            ) ASC
            "#
        )
        .fetch_all(pool)
        .await?;

        Ok(records
            .into_iter()
            .filter_map(|r| {
                r.container_ref
                    .map(|path| (r.attempt_id, path, r.git_repo_path))
            })
            .collect())
    }

    pub async fn create(
        pool: &SqlitePool,
        data: &CreateTaskAttempt,
        task_id: Uuid,
    ) -> Result<Self, TaskAttemptError> {
        let attempt_id = Uuid::new_v4();
        // let prefixed_id = format!("vibe-kanban-{}", attempt_id);
        // Insert the record into the database
        Ok(sqlx::query_as!(
            TaskAttempt,
            r#"INSERT INTO task_attempts (id, task_id, container_ref, branch, base_branch, profile, worktree_deleted, setup_completed_at)
               VALUES ($1, $2, $3, $4, $5, $6, $7, $8)
               RETURNING id as "id!: Uuid", task_id as "task_id!: Uuid", container_ref, branch, base_branch, profile as "profile!",  worktree_deleted as "worktree_deleted!: bool", setup_completed_at as "setup_completed_at: DateTime<Utc>", created_at as "created_at!: DateTime<Utc>", updated_at as "updated_at!: DateTime<Utc>""#,
            attempt_id,
            task_id,
            Option::<String>::None, // Container isn't known yet
            Option::<String>::None, // branch name isn't known yet
            data.base_branch,
            data.profile,
            false, // worktree_deleted is false during creation
            Option::<DateTime<Utc>>::None // setup_completed_at is None during creation
        )
        .fetch_one(pool)
        .await?)
    }

    pub async fn update_base_branch(
        pool: &SqlitePool,
        attempt_id: Uuid,
        new_base_branch: &str,
    ) -> Result<(), TaskAttemptError> {
        sqlx::query!(
            "UPDATE task_attempts SET base_branch = $1, updated_at = datetime('now') WHERE id = $2",
            new_base_branch,
            attempt_id,
        )
        .execute(pool)
        .await?;

        Ok(())
    }

    pub async fn resolve_container_ref(
        pool: &SqlitePool,
        container_ref: &str,
    ) -> Result<(Uuid, Uuid, Uuid), sqlx::Error> {
        let result = sqlx::query!(
            r#"SELECT ta.id as "attempt_id!: Uuid",
                      ta.task_id as "task_id!: Uuid",
                      t.project_id as "project_id!: Uuid"
               FROM task_attempts ta
               JOIN tasks t ON ta.task_id = t.id
               WHERE ta.container_ref = ?"#,
            container_ref
        )
        .fetch_optional(pool)
        .await?
        .ok_or(sqlx::Error::RowNotFound)?;

        Ok((result.attempt_id, result.task_id, result.project_id))
    }
}

use chrono::{DateTime, Utc};
use serde::{Deserialize, Serialize};
use sqlx::{FromRow, SqlitePool};
use ts_rs::TS;
use uuid::Uuid;

#[derive(Debug, Clone, FromRow, Serialize, Deserialize, TS)]
pub struct TaskTemplate {
    pub id: Uuid,
    pub project_id: Option<Uuid>, // None for global templates
    pub title: String,
    pub description: Option<String>,
    pub template_name: String,
    pub created_at: DateTime<Utc>,
    pub updated_at: DateTime<Utc>,
}

#[derive(Debug, Deserialize, TS)]
pub struct CreateTaskTemplate {
    pub project_id: Option<Uuid>,
    pub title: String,
    pub description: Option<String>,
    pub template_name: String,
}

#[derive(Debug, Deserialize, TS)]
pub struct UpdateTaskTemplate {
    pub title: Option<String>,
    pub description: Option<String>,
    pub template_name: Option<String>,
}

impl TaskTemplate {
    pub async fn find_all(pool: &SqlitePool) -> Result<Vec<Self>, sqlx::Error> {
        sqlx::query_as!(
            TaskTemplate,
            r#"SELECT id as "id!: Uuid", project_id as "project_id?: Uuid", title, description, template_name, created_at as "created_at!: DateTime<Utc>", updated_at as "updated_at!: DateTime<Utc>"
               FROM task_templates 
               ORDER BY project_id IS NULL DESC, template_name ASC"#
        )
        .fetch_all(pool)
        .await
    }

    pub async fn find_by_project_id(
        pool: &SqlitePool,
        project_id: Option<Uuid>,
    ) -> Result<Vec<Self>, sqlx::Error> {
        if let Some(pid) = project_id {
            // Return only project-specific templates
            sqlx::query_as::<_, TaskTemplate>(
                r#"SELECT id, project_id, title, description, template_name, created_at, updated_at
                   FROM task_templates 
                   WHERE project_id = ?
                   ORDER BY template_name ASC"#,
            )
            .bind(pid)
            .fetch_all(pool)
            .await
        } else {
            // Return only global templates
            sqlx::query_as!(
                TaskTemplate,
                r#"SELECT id as "id!: Uuid", project_id as "project_id?: Uuid", title, description, template_name, created_at as "created_at!: DateTime<Utc>", updated_at as "updated_at!: DateTime<Utc>"
                   FROM task_templates 
                   WHERE project_id IS NULL
                   ORDER BY template_name ASC"#
            )
            .fetch_all(pool)
            .await
        }
    }

    pub async fn find_by_id(pool: &SqlitePool, id: Uuid) -> Result<Option<Self>, sqlx::Error> {
        sqlx::query_as!(
            TaskTemplate,
            r#"SELECT id as "id!: Uuid", project_id as "project_id?: Uuid", title, description, template_name, created_at as "created_at!: DateTime<Utc>", updated_at as "updated_at!: DateTime<Utc>"
               FROM task_templates 
               WHERE id = $1"#,
            id
        )
        .fetch_optional(pool)
        .await
    }

    pub async fn create(pool: &SqlitePool, data: &CreateTaskTemplate) -> Result<Self, sqlx::Error> {
        let id = Uuid::new_v4();
        sqlx::query_as!(
            TaskTemplate,
            r#"INSERT INTO task_templates (id, project_id, title, description, template_name) 
               VALUES ($1, $2, $3, $4, $5) 
               RETURNING id as "id!: Uuid", project_id as "project_id?: Uuid", title, description, template_name, created_at as "created_at!: DateTime<Utc>", updated_at as "updated_at!: DateTime<Utc>""#,
            id,
            data.project_id,
            data.title,
            data.description,
            data.template_name
        )
        .fetch_one(pool)
        .await
    }

    pub async fn update(
        pool: &SqlitePool,
        id: Uuid,
        data: &UpdateTaskTemplate,
    ) -> Result<Self, sqlx::Error> {
        // Get existing template first
        let existing = Self::find_by_id(pool, id)
            .await?
            .ok_or(sqlx::Error::RowNotFound)?;

        // Use let bindings to create longer-lived values
        let title = data.title.as_ref().unwrap_or(&existing.title);
        let description = data.description.as_ref().or(existing.description.as_ref());
        let template_name = data
            .template_name
            .as_ref()
            .unwrap_or(&existing.template_name);

        sqlx::query_as!(
            TaskTemplate,
            r#"UPDATE task_templates 
               SET title = $2, description = $3, template_name = $4, updated_at = datetime('now', 'subsec')
               WHERE id = $1 
               RETURNING id as "id!: Uuid", project_id as "project_id?: Uuid", title, description, template_name, created_at as "created_at!: DateTime<Utc>", updated_at as "updated_at!: DateTime<Utc>""#,
            id,
            title,
            description,
            template_name
        )
        .fetch_one(pool)
        .await
    }

    pub async fn delete(pool: &SqlitePool, id: Uuid) -> Result<u64, sqlx::Error> {
        let result = sqlx::query!("DELETE FROM task_templates WHERE id = $1", id)
            .execute(pool)
            .await?;
        Ok(result.rows_affected())
    }
}

use chrono::{DateTime, Utc}; use serde::{Deserialize, Serialize}; use sqlx::{FromRow, SqlitePool, Type}; use ts_rs::TS; use uuid::Uuid;
use super::project::Project;
#[derive(Debug, Clone, Type, Serialize, Deserialize, PartialEq, TS)] #[sqlx(type_name = "task_status", rename_all = "lowercase")] #[serde(rename_all = "lowercase")] pub enum TaskStatus { Todo, InProgress, InReview, Done, Cancelled, }
#[derive(Debug, Clone, FromRow, Serialize, Deserialize, TS)] pub struct Task { pub id: Uuid, pub project_id: Uuid, // Foreign key to Project pub title: String, pub description: Option<String>, pub status: TaskStatus, pub parent_task_attempt: Option<Uuid>, // Foreign key to parent TaskAttempt pub created_at: DateTime<Utc>, pub updated_at: DateTime<Utc>, }
#[derive(Debug, Clone, Serialize, Deserialize, TS)] pub struct TaskWithAttemptStatus { pub id: Uuid, pub project_id: Uuid, pub title: String, pub description: Option<String>, pub status: TaskStatus, pub parent_task_attempt: Option<Uuid>, pub created_at: DateTime<Utc>, pub updated_at: DateTime<Utc>, pub has_in_progress_attempt: bool, pub has_merged_attempt: bool, pub last_attempt_failed: bool, pub profile: String, }
#[derive(Debug, Deserialize, TS)] pub struct CreateTask { pub project_id: Uuid, pub title: String, pub description: Option<String>, pub parent_task_attempt: Option<Uuid>, pub image_ids: Option<Vec<Uuid>>, }
#[derive(Debug, Deserialize, TS)] pub struct UpdateTask { pub title: Option<String>, pub description: Option<String>, pub status: Option<TaskStatus>, pub parent_task_attempt: Option<Uuid>, pub image_ids: Option<Vec<Uuid>>, }
impl Task { pub fn to_prompt(&self) -> String { if let Some(description) = &self.description { format!("Title: {}\n\nDescription:{}", &self.title, description) } else { self.title.clone() } }
pub async fn parent_project(&self, pool: &SqlitePool) -> Result<Option<Project>, sqlx::Error> { Project::find_by_id(pool, self.project_id).await }
pub async fn find_by_project_id_with_attempt_status( pool: &SqlitePool, project_id: Uuid, ) -> Result<Vec<TaskWithAttemptStatus>, sqlx::Error> { let records = sqlx::query!( r#"SELECT t.id AS "id!: Uuid", t.project_id AS "project_id!: Uuid", t.title, t.description, t.status AS "status!: TaskStatus", t.parent_task_attempt AS "parent_task_attempt: Uuid", t.created_at AS "created_at!: DateTime<Utc>", t.updated_at AS "updated_at!: DateTime<Utc>",
CASE WHEN EXISTS ( SELECT 1 FROM task_attempts ta JOIN execution_processes ep ON ep.task_attempt_id = ta.id WHERE ta.task_id = t.id AND ep.status = 'running' AND ep.run_reason IN ('setupscript','cleanupscript','codingagent') LIMIT 1 ) THEN 1 ELSE 0 END AS "has_in_progress_attempt!: i64",
CASE WHEN ( SELECT ep.status FROM task_attempts ta JOIN execution_processes ep ON ep.task_attempt_id = ta.id WHERE ta.task_id = t.id AND ep.run_reason IN ('setupscript','cleanupscript','codingagent') ORDER BY ep.created_at DESC LIMIT 1 ) IN ('failed','killed') THEN 1 ELSE 0 END AS "last_attempt_failed!: i64",
( SELECT ta.profile FROM task_attempts ta WHERE ta.task_id = t.id ORDER BY ta.created_at DESC LIMIT 1 ) AS "profile!: String"
FROM tasks t WHERE t.project_id = $1 ORDER BY t.created_at DESC"#, project_id ) .fetch_all(pool) .await?;
let tasks = records .into_iter() .map(|rec| TaskWithAttemptStatus { id: rec.id, project_id: rec.project_id, title: rec.title, description: rec.description, status: rec.status, parent_task_attempt: rec.parent_task_attempt, created_at: rec.created_at, updated_at: rec.updated_at, has_in_progress_attempt: rec.has_in_progress_attempt != 0, has_merged_attempt: false, // TODO use merges table last_attempt_failed: rec.last_attempt_failed != 0, profile: rec.profile, }) .collect();
Ok(tasks) }
pub async fn find_by_id(pool: &SqlitePool, id: Uuid) -> Result<Option<Self>, sqlx::Error> { sqlx::query_as!( Task, r#"SELECT id as "id!: Uuid", project_id as "project_id!: Uuid", title, description, status as "status!: TaskStatus", parent_task_attempt as "parent_task_attempt: Uuid", created_at as "created_at!: DateTime<Utc>", updated_at as "updated_at!: DateTime<Utc>" FROM tasks WHERE id = $1"#, id ) .fetch_optional(pool) .await }
pub async fn find_by_rowid(pool: &SqlitePool, rowid: i64) -> Result<Option<Self>, sqlx::Error> { sqlx::query_as!( Task, r#"SELECT id as "id!: Uuid", project_id as "project_id!: Uuid", title, description, status as "status!: TaskStatus", parent_task_attempt as "parent_task_attempt: Uuid", created_at as "created_at!: DateTime<Utc>", updated_at as "updated_at!: DateTime<Utc>" FROM tasks WHERE rowid = $1"#, rowid ) .fetch_optional(pool) .await }
pub async fn find_by_id_and_project_id( pool: &SqlitePool, id: Uuid, project_id: Uuid, ) -> Result<Option<Self>, sqlx::Error> { sqlx::query_as!( Task, r#"SELECT id as "id!: Uuid", project_id as "project_id!: Uuid", title, description, status as "status!: TaskStatus", parent_task_attempt as "parent_task_attempt: Uuid", created_at as "created_at!: DateTime<Utc>", updated_at as "updated_at!: DateTime<Utc>" FROM tasks WHERE id = $1 AND project_id = $2"#, id, project_id ) .fetch_optional(pool) .await }
pub async fn create( pool: &SqlitePool, data: &CreateTask, task_id: Uuid, ) -> Result<Self, sqlx::Error> { sqlx::query_as!( Task, r#"INSERT INTO tasks (id, project_id, title, description, status, parent_task_attempt) VALUES ($1, $2, $3, $4, $5, $6) RETURNING id as "id!: Uuid", project_id as "project_id!: Uuid", title, description, status as "status!: TaskStatus", parent_task_attempt as "parent_task_attempt: Uuid", created_at as "created_at!: DateTime<Utc>", updated_at as "updated_at!: DateTime<Utc>""#, task_id, data.project_id, data.title, data.description, TaskStatus::Todo as TaskStatus, data.parent_task_attempt ) .fetch_one(pool) .await }
pub async fn update( pool: &SqlitePool, id: Uuid, project_id: Uuid, title: String, description: Option<String>, status: TaskStatus, parent_task_attempt: Option<Uuid>, ) -> Result<Self, sqlx::Error> { sqlx::query_as!( Task, r#"UPDATE tasks SET title = $3, description = $4, status = $5, parent_task_attempt = $6 WHERE id = $1 AND project_id = $2 RETURNING id as "id!: Uuid", project_id as "project_id!: Uuid", title, description, status as "status!: TaskStatus", parent_task_attempt as "parent_task_attempt: Uuid", created_at as "created_at!: DateTime<Utc>", updated_at as "updated_at!: DateTime<Utc>""#, id, project_id, title, description, status, parent_task_attempt ) .fetch_one(pool) .await }
pub async fn update_status( pool: &SqlitePool, id: Uuid, status: TaskStatus, ) -> Result<(), sqlx::Error> { sqlx::query!( "UPDATE tasks SET status = $2, updated_at = CURRENT_TIMESTAMP WHERE id = $1", id, status ) .execute(pool) .await?; Ok(()) }
pub async fn delete(pool: &SqlitePool, id: Uuid) -> Result<u64, sqlx::Error> { let result = sqlx::query!("DELETE FROM tasks WHERE id = $1", id) .execute(pool) .await?; Ok(result.rows_affected()) }
pub async fn exists( pool: &SqlitePool, id: Uuid, project_id: Uuid, ) -> Result<bool, sqlx::Error> { let result = sqlx::query!( "SELECT id as \"id!: Uuid\" FROM tasks WHERE id = $1 AND project_id = $2", id, project_id ) .fetch_optional(pool) .await?; Ok(result.is_some()) }
pub async fn find_related_tasks_by_attempt_id( pool: &SqlitePool, attempt_id: Uuid, ) -> Result<Vec<Self>, sqlx::Error> { // Find both children and parent for this attempt sqlx::query_as!( Task, r#"SELECT DISTINCT t.id as "id!: Uuid", t.project_id as "project_id!: Uuid", t.title, t.description, t.status as "status!: TaskStatus", t.parent_task_attempt as "parent_task_attempt: Uuid", t.created_at as "created_at!: DateTime<Utc>", t.updated_at as "updated_at!: DateTime<Utc>" FROM tasks t WHERE ( -- Find children: tasks that have this attempt as parent t.parent_task_attempt = $1 ) OR ( -- Find parent: task that owns the parent attempt of current task EXISTS ( SELECT 1 FROM tasks current_task JOIN task_attempts parent_attempt ON current_task.parent_task_attempt = parent_attempt.id WHERE parent_attempt.task_id = t.id ) ) -- Exclude the current task itself to prevent circular references AND t.id != (SELECT task_id FROM task_attempts WHERE id = $1) ORDER BY t.created_at DESC"#, attempt_id, ) .fetch_all(pool) .await } }

