            <CardContent>
              <TaskTemplateManager isGlobal={true} />
            </CardContent>
          </Card>

          <Card>
            <CardHeader>
              <CardTitle className="flex items-center gap-2">
                Agent Profiles
              </CardTitle>
              <CardDescription>
                Configure coding agent profiles with specific command-line
                parameters.
              </CardDescription>
            </CardHeader>
            <CardContent className="space-y-4">
              {profilesError && (
                <Alert variant="destructive">
                  <AlertDescription>{profilesError}</AlertDescription>
                </Alert>
              )}

              {profilesSuccess && (
                <Alert className="border-green-200 bg-green-50 text-green-800 dark:border-green-800 dark:bg-green-950 dark:text-green-200">
                  <AlertDescription className="font-medium">
                    ✓ Profiles saved successfully!
                  </AlertDescription>
                </Alert>
              )}

              <div className="space-y-4">
                <div className="space-y-2">
                  <Label htmlFor="profiles-editor">
                    Profiles Configuration
                  </Label>
                  <JSONEditor
                    id="profiles-editor"
                    placeholder={
                      profilesLoading
                        ? 'Loading profiles...'
                        : '{\n  "profiles": [\n    {\n      "label": "my-custom-profile",\n      "agent": "ClaudeCode",\n      "command": {...}\n    }\n  ]\n}'
                    }
                    value={profilesLoading ? 'Loading...' : profilesContent}
                    onChange={handleProfilesChange}
                    disabled={profilesLoading}
                    minHeight={300}
                  />
                </div>

                <div className="space-y-2">
                  {!profilesError && profilesPath && (
                    <p className="text-sm text-muted-foreground">
                      <span className="font-medium">Configuration file:</span>{' '}
                      <span className="font-mono text-xs">{profilesPath}</span>
                    </p>
                  )}
                  <p className="text-sm text-muted-foreground">
                    Edit coding agent profiles. Each profile needs a unique
                    label, agent type, and command configuration.
                  </p>
                </div>

                <div className="flex justify-end pt-2">
                  <Button
                    onClick={handleSaveProfiles}
                    disabled={
                      profilesSaving ||
                      profilesLoading ||
                      !!profilesError ||
                      profilesSuccess
                    }
                    className={
                      profilesSuccess ? 'bg-green-600 hover:bg-green-700' : ''
                    }
                  >
                    {profilesSaving && (
                      <Loader2 className="mr-2 h-4 w-4 animate-spin" />
                    )}
                    {profilesSuccess && <span className="mr-2">✓</span>}
                    {profilesSuccess ? 'Profiles Saved!' : 'Save Profiles'}
                  </Button>
                </div>
              </div>
            </CardContent>
          </Card>

          <Card>
            <CardHeader>
              <CardTitle>Safety & Disclaimers</CardTitle>
              <CardDescription>
                Manage safety warnings and acknowledgments.
              </CardDescription>
            </CardHeader>
            <CardContent className="space-y-6">
              <div className="space-y-2">
                <div className="flex items-center justify-between">
                  <div>
                    <Label>Disclaimer Status</Label>
                    <p className="text-sm text-muted-foreground">
                      {config.disclaimer_acknowledged
                        ? 'You have acknowledged the safety disclaimer.'
                        : 'The safety disclaimer has not been acknowledged.'}
                    </p>
                  </div>
                  <Button
                    onClick={resetDisclaimer}
                    variant="outline"
                    size="sm"
                    disabled={!config.disclaimer_acknowledged}
                  >
                    Reset Disclaimer
                  </Button>
                </div>
                <p className="text-xs text-muted-foreground">
                  Resetting the disclaimer will require you to acknowledge the
                  safety warning again.
                </p>
              </div>
              <div className="space-y-2">
                <div className="flex items-center justify-between">
                  <div>
                    <Label>Onboarding Status</Label>
                    <p className="text-sm text-muted-foreground">
                      {config.onboarding_acknowledged
                        ? 'You have completed the onboarding process.'
                        : 'The onboarding process has not been completed.'}
                    </p>
                  </div>
                  <Button
                    onClick={resetOnboarding}
                    variant="outline"
                    size="sm"
                    disabled={!config.onboarding_acknowledged}
                  >
                    Reset Onboarding
                  </Button>
                </div>
                <p className="text-xs text-muted-foreground">
                  Resetting the onboarding will show the setup screen again.
                </p>
              </div>
              <div className="space-y-2">
                <div className="flex items-center justify-between">
                  <div>
                    <Label>Telemetry Acknowledgment</Label>
                    <p className="text-sm text-muted-foreground">
                      {config.telemetry_acknowledged
                        ? 'You have acknowledged the telemetry notice.'
                        : 'The telemetry notice has not been acknowledged.'}
                    </p>
                  </div>
                  <Button
                    onClick={() =>
                      updateConfig({ telemetry_acknowledged: false })
                    }
                    variant="outline"
                    size="sm"
                    disabled={!config.telemetry_acknowledged}
                  >
                    Reset Acknowledgment
                  </Button>
                </div>
                <p className="text-xs text-muted-foreground">
                  Resetting the acknowledgment will require you to acknowledge
                  the telemetry notice again.
                </p>
              </div>
            </CardContent>
          </Card>
        </div>

        {/* Sticky save button */}
        <div className="fixed bottom-0 left-0 right-0 bg-background/80 backdrop-blur-sm border-t p-4 z-10">
          <div className="container mx-auto max-w-4xl flex justify-end">
            <Button
              onClick={handleSave}
              disabled={saving || success}
              className={success ? 'bg-green-600 hover:bg-green-700' : ''}
            >
              {saving && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
              {success && <span className="mr-2">✓</span>}
              {success ? 'Settings Saved!' : 'Save Settings'}
            </Button>
          </div>
        </div>

        {/* Spacer to prevent content from being hidden behind sticky button */}
        <div className="h-20"></div>
      </div>
    </div>
  );
}

import { useEffect, useState } from 'react';
import { useNavigate, useParams } from 'react-router-dom';
import { Loader } from '@/components/ui/loader';
import { TaskDetailsPanel } from '@/components/tasks/TaskDetailsPanel';
import { projectsApi, tasksApi } from '@/lib/api';
import type { TaskWithAttemptStatus, Project } from 'shared/types';

export function TaskDetailsPage() {
  const { projectId, taskId, attemptId } = useParams<{
    projectId: string;
    taskId: string;
    attemptId?: string;
  }>();
  const navigate = useNavigate();

  const [task, setTask] = useState<TaskWithAttemptStatus | null>(null);
  const [project, setProject] = useState<Project | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const handleClose = () => {
    navigate(`/projects/${projectId}/tasks`, { replace: true });
  };

  const handleEditTask = (task: TaskWithAttemptStatus) => {
    // Navigate back to main task page and trigger edit
    navigate(`/projects/${projectId}/tasks/${task.id}`);
  };

  const handleDeleteTask = () => {
    // Navigate back to main task page after deletion
    // navigate(`/projects/${projectId}/tasks`);
  };

  useEffect(() => {
    const fetchData = async () => {
      if (!projectId || !taskId) {
        setError('Missing project or task ID');
        setLoading(false);
        return;
      }

      try {
        setLoading(true);

        // Fetch both project and tasks in parallel
        const [projectResult, tasksResult] = await Promise.all([
          projectsApi.getById(projectId),
          tasksApi.getAll(projectId),
        ]);

        // Find the specific task from the list (to get TaskWithAttemptStatus)
        const foundTask = tasksResult.find((t) => t.id === taskId);

        if (!foundTask) {
          setError('Task not found');
          setLoading(false);
          return;
        }

        setProject(projectResult);
        setTask(foundTask);
      } catch (err) {
        console.error('Failed to fetch task details:', err);
        setError('Failed to load task details');
      } finally {
        setLoading(false);
      }
    };

    fetchData();
  }, [projectId, taskId, attemptId]);

  if (loading) {
    return (
      <div className="min-h-screen bg-background flex items-center justify-center">
        <Loader message="Loading task details..." size={32} />
      </div>
    );
  }

  if (error) {
    return (
      <div className="min-h-screen bg-background flex items-center justify-center">
        <div className="text-center">
          <div className="text-destructive text-lg mb-4">{error}</div>
          <button
            onClick={handleClose}
            className="text-primary hover:underline"
          >
            Back to tasks
          </button>
        </div>
      </div>
    );
  }

  if (!task || !project) {
    return (
      <div className="min-h-screen bg-background flex items-center justify-center">
        <div className="text-center">
          <div className="text-muted-foreground text-lg mb-4">
            Task not found
          </div>
          <button
            onClick={handleClose}
            className="text-primary hover:underline"
          >
            Back to tasks
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-background">
      <TaskDetailsPanel
        task={task}
        projectHasDevScript={!!project.dev_script}
        projectId={projectId!}
        onClose={handleClose}
        onEditTask={handleEditTask}
        onDeleteTask={handleDeleteTask}
        hideBackdrop={true}
        hideHeader={true}
        className="w-full h-screen flex flex-col"
      />
    </div>
  );
}

import { create } from 'zustand';

type State = {
  expanded: Record<string, boolean>;
  setKey: (key: string, value: boolean) => void;
  toggleKey: (key: string, fallback?: boolean) => void;
  clear: () => void;
};

export const useExpandableStore = create<State>((set) => ({
  expanded: {},
  setKey: (key, value) =>
    set((s) =>
      s.expanded[key] === value
        ? s
        : { expanded: { ...s.expanded, [key]: value } }
    ),
  toggleKey: (key, fallback = false) =>
    set((s) => {
      const next = !(s.expanded[key] ?? fallback);
      return { expanded: { ...s.expanded, [key]: next } };
    }),
  clear: () => set({ expanded: {} }),
}));

export function useExpandable(
  key: string,
  defaultValue = false
): [boolean, (next?: boolean) => void] {
  const expandedValue = useExpandableStore((s) => s.expanded[key]);
  const setKey = useExpandableStore((s) => s.setKey);
  const toggleKey = useExpandableStore((s) => s.toggleKey);

  const set = (next?: boolean) => {
    if (typeof next === 'boolean') setKey(key, next);
    else toggleKey(key, defaultValue);
  };

  return [expandedValue ?? defaultValue, set];
}

